func (q *Queries) PageRivalVideosByViews(ctx context.Context, arg PageRivalVideosByViewsParams) ([]PageRivalVideosByViewsRow, error) {
	rows, err := q.db.Query(ctx, pageRivalVideosByViews,
		arg.ChannelID,
		arg.LongOnly,
		arg.LongMinSec,
		arg.WithinDays,
		arg.Now,
		arg.Q,
		arg.CursorID,
		arg.CursorViews,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PageRivalVideosByViewsRow{}
	for rows.Next() {
		var i PageRivalVideosByViewsRow
		if err := rows.Scan(
			&i.ID,
			&i.ChannelID,
			&i.Title,
			&i.DurationSec,
			&i.ViewCount,
			&i.PublishedText,
			&i.PublishedAt,
			&i.UploadedAt,
			&i.UploadCheckedAt,
			&i.HasCaptions,
			&i.Score,
			&i.Position,
			&i.Origin,
			&i.FirstSeenAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const rivalExists = `-- name: RivalExists :one
SELECT EXISTS(SELECT 1 FROM rival_channels WHERE id = $1)::bool AS exists
`

func (q *Queries) RivalExists(ctx context.Context, id string) (bool, error) {
	row := q.db.QueryRow(ctx, rivalExists, id)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

const uploadProbePausedUntil = `-- name: UploadProbePausedUntil :one
SELECT COALESCE(
    (SELECT ss.upload_times_next_at FROM scan_schedule ss WHERE ss.id),
    'epoch'::timestamptz
)::timestamptz AS paused_until
`

// Giờ tạm nghỉ đọc giờ đăng của luồng quét (một dòng scan_schedule; chưa có
// dòng = không nghỉ). epoch nghĩa là không nghỉ.
func (q *Queries) UploadProbePausedUntil(ctx context.Context) (pgtype.Timestamptz, error) {
	row := q.db.QueryRow(ctx, uploadProbePausedUntil)
	var paused_until pgtype.Timestamptz
	err := row.Scan(&paused_until)
	return paused_until, err
}
